"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3943],{97708:e=>{e.exports=JSON.parse('{"functions":[{"name":"GetCoins","desc":"Return the player\'s current coin balance, or 0 if the profile is not loaded.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":53,"path":"src/ServerStorage/SharedModules/CoinManager.luau"}},{"name":"AddCoins","desc":"Award `amount` coins to a single player. No-op if `amount <= 0` or the\\nprofile is not loaded. Clamps the new balance to `CoinConfig.MAX_BALANCE`,\\nthen replicates. `reason` is an optional source tag recorded in the server\\nlog only (e.g. \\"DailyChallenge\\", \\"SessionComplete\\").","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"amount","desc":"","lua_type":"number"},{"name":"reason","desc":"","lua_type":"string?"}],"returns":[],"function_type":"static","source":{"line":68,"path":"src/ServerStorage/SharedModules/CoinManager.luau"}},{"name":"DeductCoins","desc":"Atomically deduct `amount` coins from a single player. Returns `true` on\\nsuccess. Returns `false` with **no mutation** if `amount <= 0`, the profile\\nis not loaded, or the balance is insufficient. This is the contract a future\\nshop relies on.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"amount","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":98,"path":"src/ServerStorage/SharedModules/CoinManager.luau"}},{"name":"RefundCoins","desc":"Return an exact `amount` of coins to a player (e.g. a perk-unlock refund).\\nUnlike `AddCoins`, this is NOT scaled by the Fortune `CoinGainBonus` \u2014 a refund\\nmust return exactly what was paid, or unlock\u2192respec cycling could mint coins.\\nNo-op if `amount <= 0` or the profile is not loaded. Clamps to\\n`CoinConfig.MAX_BALANCE`, then replicates.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"amount","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":122,"path":"src/ServerStorage/SharedModules/CoinManager.luau"}},{"name":"Initialize","desc":"Wire up the profile lifecycle. Call exactly once per server (from a loader).","params":[],"returns":[],"function_type":"static","source":{"line":168,"path":"src/ServerStorage/SharedModules/CoinManager.luau"}}],"properties":[],"types":[],"name":"CoinManager","desc":"Place-agnostic authority for the player coin wallet. Owns the PlayerCoins\\nProfileStore profile lifecycle (one session per player, key = UserId), the\\nearn/spend/read API, and per-player replication via `CoinStateSync`.\\n\\nRuns in BOTH the lobby and gameplay places. Coin *sources* (gameplay-session\\ncompletion, daily/weekly challenges) and *sinks* (shop) are SEPARATE systems\\nthat call `AddCoins` / `DeductCoins`; they are not part of this module.\\n\\nCross-place: `STORE_NAME` + `tostring(UserId)` key are identical in every\\nplace of the universe, so the same DataStore record is shared. ProfileStore\\nsession-locking serializes the lobby\u2194gameplay teleport handoff automatically.","realm":["Server"],"source":{"line":18,"path":"src/ServerStorage/SharedModules/CoinManager.luau"}}')}}]);